// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }
    function testFuzz_property(address lrtConfigAddr) public {
        vm.assume(lrtConfigAddr != address(0));
        try c.initialize(lrtConfigAddr) {} catch {}
        bool pausedResult = c.paused();
        bool unpausedResult;
        try c.unpause() { unpausedResult = c.paused(); } catch { unpausedResult = pausedResult; }
        assertTrue(pausedResult != unpausedResult || !pausedResult);
    }
}
